ee:message.ee:set-payload:
%dw 2.0
	output application/xml
	ns ps http://itmo.ru/person-service
	---
	ps#searchPersonsRequest: {
		ps#pageRequest: {
			ps#page: vars.page as Number,
			ps#size: vars.size as Number
		}
	}

%dw 2.0
	output application/json

	var xmlBody = write(payload.body, "application/xml")
	var contentPattern = /<(?:\w+:)?content[^>]*>([\s\S]*?)<\/(?:\w+:)?content>/
	var allContent = (xmlBody scan contentPattern) map ((match) -> match[1])

	fun extractTag(xml: String, tagName: String): String | Null = do {
		var pattern = "<(?:\\w+:)?" ++ tagName ++ "[^>]*>(.*?)</(?:\\w+:)?" ++ tagName ++ ">"
		var matches = (xml scan pattern)
		---
		if (matches[0]?) matches[0][1] else null
	}

	fun parseLocation(locationXml: String): Object = {
		x: extractTag(locationXml, "x") as Number default null,
		y: extractTag(locationXml, "y") as Number default null,
		z: extractTag(locationXml, "z") as Number default null,
		name: extractTag(locationXml, "name") default null
	}

	fun parseCoordinates(coordXml: String): Object = {
		x: extractTag(coordXml, "x") as Number,
		y: extractTag(coordXml, "y") as Number
	}

	fun parsePerson(personXml: String): Object = do {
		var locationXml = (personXml scan /<(?:\w+:)?location[^>]*>([\s\S]*?)<\/(?:\w+:)?location>/)
		var coordXml = (personXml scan /<(?:\w+:)?coordinates[^>]*>([\s\S]*?)<\/(?:\w+:)?coordinates>/)
		var rawCreationDate = extractTag(personXml, "creationDate")
		var cleanCreationDate = if (rawCreationDate != null) (rawCreationDate splitBy /[\+\-]\d{2}:\d{2}/)[0] else null
		---
		{
			id: extractTag(personXml, "id") as Number,
			name: extractTag(personXml, "name"),
			coordinates: if (coordXml[0]?) parseCoordinates(coordXml[0][1]) else null,
			creationDate: cleanCreationDate,
			height: extractTag(personXml, "height") as Number default null,
			weight: extractTag(personXml, "weight") as Number,
			hairColor: extractTag(personXml, "hairColor"),
			eyeColor: extractTag(personXml, "eyeColor"),
			nationality: extractTag(personXml, "nationality"),
			location: if (locationXml[0]?) parseLocation(locationXml[0][1]) else null
		}
	}
	---
	allContent map parsePerson($)

%dw 2.0
output application/xml
ns ps http://itmo.ru/person-service
---
ps#createPersonRequest: {
    ps#person: {
        ps#name: payload.name,
        ps#coordinates: {
            ps#x: payload.coordinates.x,
            ps#y: payload.coordinates.y
        },
        ps#height: payload.height,
        ps#weight: payload.weight,
        ps#hairColor: payload.hairColor,
        ps#eyeColor: payload.eyeColor,
        ps#nationality: payload.nationality,
        ps#location: if (payload.location != null) {
            ps#x: payload.location.x,
            ps#y: payload.location.y,
            ps#z: payload.location.z,
            ps#name: payload.location.name
        } else null
    }
}

%dw 2.0
output application/json

fun extractTag(xml: String, tagName: String): String | Null = do {
    var pattern = "<(?:\\w+:)?" ++ tagName ++ "[^>]*>(.*?)</(?:\\w+:)?" ++ tagName ++ ">"
    var matches = (xml scan pattern)
    ---
    if (matches[0]?) matches[0][1] else null
}

fun parseCoordinates(coordXml: String): Object | Null = do {
    if (coordXml == null) null
    else {
        x: extractTag(coordXml, "x") as Number,
        y: extractTag(coordXml, "y") as Number
    }
}

fun parseLocation(locXml: String): Object | Null = do {
    if (locXml == null) null
    else {
        x: extractTag(locXml, "x") as Number,
        y: extractTag(locXml, "y") as Number,
        z: extractTag(locXml, "z") as Number,
        name: extractTag(locXml, "name")
    }
}
---
do {
    var xmlBody = write(payload.body, "application/xml")

    var personPattern = /<(?:\w+:)?createPersonResponse[^>]*>([\s\S]*?)<\/(?:\w+:)?createPersonResponse>/
    var personXml = (xmlBody scan personPattern)[0][1]

    var coordPattern = /<(?:\w+:)?coordinates[^>]*>([\s\S]*?)<\/(?:\w+:)?coordinates>/
    var coordXml = (personXml scan coordPattern)[0][1]

    var locPattern = /<(?:\w+:)?location[^>]*>([\s\S]*?)<\/(?:\w+:)?location>/
    var locMatches = personXml scan locPattern
    var locXml = if (sizeOf(locMatches) > 0) locMatches[0][1] else null

    var rawCreationDate = extractTag(personXml, "creationDate")
    var cleanCreationDate = if (rawCreationDate != null)
        (rawCreationDate splitBy /[\+\-]\d{2}:\d{2}/)[0]
        else null

    var heightValue = extractTag(personXml, "height")
    ---
    {
        id: extractTag(personXml, "id") as Number,
        name: extractTag(personXml, "name"),
        coordinates: parseCoordinates(coordXml),
        creationDate: cleanCreationDate,
        height: if (heightValue != null and heightValue != "") heightValue as Number else null,
        weight: extractTag(personXml, "weight") as Number,
        hairColor: extractTag(personXml, "hairColor"),
        eyeColor: extractTag(personXml, "eyeColor"),
        nationality: extractTag(personXml, "nationality"),
        location: parseLocation(locXml)
    }
}

%dw 2.0 output application/json
