var errorDesc = lower(error.description default "")
var detailedDesc = lower(error.detailedDescription default "")
var causeMsg = lower(error.cause.message default "")
var errorMsgRaw = error.detailedDescription default error.cause.message default error.description default ""
var allErrorText = lower(errorDesc ++ " " ++ detailedDesc ++ " " ++ causeMsg)

var isNotFound =
  (allErrorText contains "not found") or
  (allErrorText contains "does not exist") or
  (allErrorText contains "personnotfound") or
  (detailedDesc contains "person with id") and (detailedDesc contains "not found") or
  (causeMsg contains "not found") or
  (causeMsg contains "does not exist")

var isValidationError =
  (allErrorText contains "validation") or
  (allErrorText contains "invalid") or
  (allErrorText contains "must be") or
  (allErrorText contains "cannot be")
---
if (isNotFound) {
  error: "PERSON_NOT_FOUND",
  message: errorMsgRaw,
  timestamp: now(),
  path: attributes.requestPath
} else if (isValidationError) {
  error: "VALIDATION_ERROR",
  message: errorMsgRaw,
  timestamp: now(),
  path: attributes.requestPath
} else {
  error: "BACKEND_ERROR",
  message: errorMsgRaw,
  timestamp: now(),
  path: attributes.requestPath
}

